    "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum TenantStatus {\n  ONBOARDING\n  ACTIVE\n  SUSPENDED\n}\n\nenum UserStatus {\n  INVITED\n  ACTIVE\n  SUSPENDED\n}\n\nenum DocumentLevel {\n  LEVEL_1\n  LEVEL_2\n  LEVEL_3\n  LEVEL_4\n}\n\nenum DocumentStatus {\n  DRAFT\n  DOCUMENT_CONTROL_REVIEW\n  PENDING_APPROVAL\n  APPROVED\n  PUBLISHED\n  RETURNED_FOR_CORRECTION\n  SUPERSEDED\n  RETIRED\n}\n\nenum WorkflowAssignmentType {\n  PREPARED_BY\n  REVIEWED_BY\n  APPROVED_BY\n}\n\nenum ApprovalDecisionType {\n  APPROVED\n  RETURNED_FOR_CORRECTION\n}\n\nmodel Tenant {\n  id        String       @id @default(uuid())\n  name      String\n  slug      String       @unique\n  subdomain String       @unique\n  status    TenantStatus @default(ONBOARDING)\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n  users     User[]\n  documents Document[]\n}\n\nmodel User {\n  id            String               @id @default(uuid())\n  tenantId      String?\n  email         String               @unique\n  name          String\n  designation   String?\n  isTenantAdmin Boolean              @default(false)\n  status        UserStatus           @default(INVITED)\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n  tenant        Tenant?              @relation(fields: [tenantId], references: [id], onDelete: SetNull)\n  assignments   WorkflowAssignment[]\n  approvals     ApprovalDecision[]\n}\n\nmodel Document {\n  id            String             @id @default(uuid())\n  tenantId      String\n  title         String\n  controlNumber String\n  level         DocumentLevel\n  status        DocumentStatus     @default(DRAFT)\n  createdAt     DateTime           @default(now())\n  updatedAt     DateTime           @updatedAt\n  tenant        Tenant             @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  versions      DocumentVersion[]\n  relatedFrom   DocumentRelation[] @relation(\"DocumentRelationFrom\")\n  relatedTo     DocumentRelation[] @relation(\"DocumentRelationTo\")\n\n  @@unique([tenantId, controlNumber])\n  @@index([tenantId, status])\n  @@index([tenantId, level])\n}\n\nmodel DocumentVersion {\n  id                 String                @id @default(uuid())\n  documentId         String\n  versionLabel       String\n  revisionNumber     Int\n  effectiveDate      DateTime?\n  nextReviewDate     DateTime?\n  purpose            String?\n  scope              String?\n  responsibilities   String?\n  procedureContent   String?\n  recordsDescription String?\n  relatedDocuments   String?\n  complianceNote     String?\n  createdAt          DateTime              @default(now())\n  document           Document              @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  assignments        WorkflowAssignment[]\n  approvals          ApprovalDecision[]\n  complianceRefs     ComplianceReference[]\n  revisionHistory    RevisionHistory[]\n\n  @@unique([documentId, revisionNumber])\n  @@index([documentId, effectiveDate])\n}\n\nmodel WorkflowAssignment {\n  id          String                 @id @default(uuid())\n  versionId   String\n  userId      String\n  type        WorkflowAssignmentType\n  assignedAt  DateTime               @default(now())\n  completedAt DateTime?\n  version     DocumentVersion        @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  user        User                   @relation(fields: [userId], references: [id], onDelete: Restrict)\n\n  @@unique([versionId, type])\n  @@index([userId, type])\n}\n\nmodel ApprovalDecision {\n  id        String               @id @default(uuid())\n  versionId String\n  userId    String\n  decision  ApprovalDecisionType\n  comment   String?\n  decidedAt DateTime             @default(now())\n  version   DocumentVersion      @relation(fields: [versionId], references: [id], onDelete: Cascade)\n  user      User                 @relation(fields: [userId], references: [id], onDelete: Restrict)\n\n  @@index([versionId, decidedAt])\n  @@index([userId, decision])\n}\n\nmodel ComplianceReference {\n  id          String          @id @default(uuid())\n  versionId   String\n  standard    String\n  edition     String?\n  clause      String\n  description String?\n  version     DocumentVersion @relation(fields: [versionId], references: [id], onDelete: Cascade)\n\n  @@index([versionId])\n}\n\nmodel RevisionHistory {\n  id                String          @id @default(uuid())\n  versionId         String\n  pageNumber        String?\n  revisionNumber    String\n  changeDescription String\n  createdAt         DateTime        @default(now())\n  version           DocumentVersion @relation(fields: [versionId], references: [id], onDelete: Cascade)\n\n  @@index([versionId])\n}\n\nmodel DocumentRelation {\n  id             String   @id @default(uuid())\n  fromDocumentId String\n  toDocumentId   String\n  relationLabel  String?\n  fromDocument   Document @relation(\"DocumentRelationFrom\", fields: [fromDocumentId], references: [id], onDelete: Cascade)\n  toDocument     Document @relation(\"DocumentRelationTo\", fields: [toDocumentId], references: [id], onDelete: Cascade)\n\n  @@unique([fromDocumentId, toDocumentId])\n  @@index([toDocumentId])\n}\n",
